          border-bottom: 1px solid rgba(38, 85, 115, 0.15);
        }
        #storybook-highlights-menu .menu-items, #storybook-highlights-menu .menu-items li {
          padding: 0;
        }
        #storybook-highlights-menu .menu-item {
          display: flex;
        }
        #storybook-highlights-menu .menu-item-content {
